def parse_json(json_str):
    if not json_str:
        raise ValueError("Invalid JSON string: empty string")
    if not json_str.startswith('{') and not json_str.startswith('['):
        raise ValueError("Invalid JSON string: not a valid JSON object or array")
    stack = []
    obj = None
    for i, c in enumerate(json_str):
        if c == '{':
            stack.append(obj)
            obj = {}
        elif c == '[':
            stack.append(obj)
            obj = []
        elif c == '}':
            if not stack:
                raise ValueError("Invalid JSON string: unmatched '{'")
            obj = stack.pop()
        elif c == ']':
            if not stack:
                raise ValueError("Invalid JSON string: unmatched '['")
            obj = stack.pop()
        elif c == ':':
            if not stack:
                raise ValueError("Invalid JSON string: unmatched ':'")
            if isinstance(obj, dict):
                obj[json_str[i - 1]] = None
            elif isinstance(obj, list):
                obj.append(None)
            else:
                raise ValueError("Invalid JSON string: unexpected ':'")
        elif c == ',':
            if not stack:
                raise ValueError("Invalid JSON string: unmatched ','")
            if isinstance(obj, dict):
                obj[json_str[i - 1]] = None
            elif isinstance(obj, list):
                obj.append(None)
            else:
                raise ValueError("Invalid JSON string: unexpected ','")
        elif c == '"':
            if not stack:
                raise ValueError("Invalid JSON string: unmatched '"'")
            if isinstance(obj, dict):
                obj[json_str[i - 1]] = None
            elif isinstance(obj, list):
                obj.append(None)
            else:
                raise ValueError("Invalid JSON string: unexpected '"'")
        elif c == 't':
            if not stack:
                raise ValueError("Invalid JSON string: unmatched 't'")
            if isinstance(obj, dict):
                obj[json_str[i - 1]] = True
            elif isinstance(obj, list):
                obj.append(True)
            else:
                raise ValueError("Invalid JSON string: unexpected 't'")
        elif c == 'f':
            if not stack:
                raise ValueError("Invalid JSON string: unmatched 'f'")
            if isinstance(obj, dict):
                obj[json_str[i - 1]] = False
            elif isinstance(obj, list):
                obj.append(False)
            else:
                raise ValueError("Invalid JSON string: unexpected 'f'")
        elif c == 'n':
            if not stack:
                raise ValueError("Invalid JSON string: unmatched 'n'")
            if isinstance(obj, dict):
                obj[json_str[i - 1]] = None
            elif isinstance(obj, list):
                obj.append(None)
            else:
                raise ValueError("Invalid JSON string: unexpected 'n'")
        elif c == '0' <= c <= '9':
            if not stack:
                raise ValueError("Invalid JSON string: unmatched number")
            if isinstance(obj, dict):
                obj[json_str[i - 1]] = int(c)
            elif isinstance(obj, list):
                obj.append(int(c))
            else:
                raise ValueError("Invalid JSON string: unexpected number")
        elif c == '.':
            if not stack:
                raise ValueError("Invalid JSON string: unmatched '.'")
            if isinstance(obj, dict):
                obj[json_str[i - 1]] = float(c)
            elif isinstance(obj, list):
                obj.append(float(c))
            else:
                raise ValueError("Invalid JSON string: unexpected '.'")
        elif c == 'e' or c == 'E':
            if not stack:
                raise ValueError("Invalid JSON string: unmatched 'e'")
            if isinstance(obj, dict):
                obj[json_str[i - 1]] = float(c)
            elif isinstance(obj, list):
                obj.append(float(c))
            else:
                raise ValueError("Invalid JSON string: unexpected 'e'")
        elif c == ' ':
            continue
        else:
            raise ValueError("Invalid JSON string: unexpected character")
    return obj

